"""Calculates and prints a record's percentage and status."""

class Record:
    """Stores a record's label, value, and limit."""

    def __init__(self, label, value, limit):
        """Initialises the record's attributes."""
        self.label = label
        self.value = value
        self.limit = limit

    def percent(self):
        """Calculates the percentage of the limit used."""
        return (self.value / self.limit) * 100

    def status(self):
        """Returns the status based on the percentage."""
        if self.percent() >= 100:
            return "OVER LIMIT"
        elif self.percent() >= 90:
            return "WARNING"
        else:
            return "OK"


