"""### D10. A class-level counter

1. Define a new, small class `Counted`. Directly under the `class` line (not inside `__init__`),
   add `count = 0`.
2. In `__init__(self)`, add 1 to `Counted.count`.
3. Create three `Counted` objects, then print `Counted.count`.

**Expected output:** `3`

Add a comment explaining why the count is shared by every object instead of each object having its own.
"""

# D10
class Counted:
    """A class that maintains a shared counter of all instances created."""
    count = 0

    def __init__(self):
        """Increment the class-level counter upon instantiation."""
        Counted.count += 1

a = Counted()
b = Counted()
c = Counted()

print(Counted.count)
# count is a class variable defined directly under the class block (not inside __init__).
# Because it belongs to the class itself rather than any individual instance (self),
# there is only one shared counter that all objects access and modify.

"""### D11. Load objects from a file

`records_sample.txt` (in this `LAB` folder) has one record per line, like `R-001,87,100`.

1. Write `load_records(path)` that reads the file and returns a list of `Record` objects
   (convert `value` and `limit` with `float()`).
2. Loop over the list and print each record's label and status.

**Expected output:** the same three lines as D9.
"""

# D11

"""Loads records from a file and prints their labels and statuses."""

def load_records(path):
    """Reads records from a file and returns a list of Record objects."""

    records = []

    with open(path, "r") as file:
        for line in file:
            label, value, limit = line.strip().split(",")
            r = Record(label, float(value), float(limit))
            records.append(r)

    return records


records = load_records("records_sample.txt")

for r in records:
    print(r.label, r.status())

